'use server';

import { updateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  // TODO: Add your database logic here to create the post
  // Example: await db.posts.create({ title, content });

  // Invalidate the "posts" cache tag
  // updateTag ensures no stale content is served - the next page load will wait for fresh data
  updateTag('posts');

  return { success: true };
}

